34	public class InstanceUtils {
35	  private InstanceUtils() {
36	  }
37	
38	  public static final String POOL_KEY = "pool";
39	
40	  /**
41	   * Returns the Helix instance id (e.g. {@code Server_localhost_1234}) for the given instance.
42	   */
43	  public static String getHelixInstanceId(Instance instance) {
44	    String prefix;
45	    switch (instance.getType()) {
46	      case CONTROLLER:
47	        prefix = Helix.PREFIX_OF_CONTROLLER_INSTANCE;
48	        break;
49	      case BROKER:
50	        prefix = Helix.PREFIX_OF_BROKER_INSTANCE;
51	        break;
52	      case SERVER:
53	        prefix = Helix.PREFIX_OF_SERVER_INSTANCE;
54	        break;
55	      case MINION:
56	        prefix = Helix.PREFIX_OF_MINION_INSTANCE;
57	        break;
58	      default:
59	        throw new IllegalStateException();
60	    }
61	    return prefix + instance.getHost() + "_" + instance.getPort();
62	  }
63	
64	  public static String getServerAdminEndpoint(InstanceConfig instanceConfig) {
65	    // Backward-compatible with legacy hostname of format 'Server_<hostname>'
66	    String hostname = instanceConfig.getHostName();
67	    if (hostname.startsWith(Helix.PREFIX_OF_SERVER_INSTANCE)) {
68	      hostname = hostname.substring(Helix.SERVER_INSTANCE_PREFIX_LENGTH);
69	    }
70	    return getServerAdminEndpoint(instanceConfig, hostname, CommonConstants.HTTP_PROTOCOL);
71	  }
72	
73	  public static String getServerAdminEndpoint(InstanceConfig instanceConfig, String hostname, String defaultProtocol) {
74	    String protocol = defaultProtocol;
75	    int port = CommonConstants.Server.DEFAULT_ADMIN_API_PORT;
76	    int adminPort = instanceConfig.getRecord().getIntField(Helix.Instance.ADMIN_PORT_KEY, -1);
77	    int adminHttpsPort = instanceConfig.getRecord().getIntField(Helix.Instance.ADMIN_HTTPS_PORT_KEY, -1);
78	    // NOTE: preference for insecure is sub-optimal, but required for incremental upgrade scenarios
79	    if (adminPort > 0) {
80	      protocol = CommonConstants.HTTP_PROTOCOL;
81	      port = adminPort;
82	    } else if (adminHttpsPort > 0) {
83	      protocol = CommonConstants.HTTPS_PROTOCOL;
84	      port = adminHttpsPort;
85	    }
86	    return String.format("%s://%s:%d", protocol, hostname, port);
87	  }
88	
89	  /**
90	   * Returns the Helix InstanceConfig for the given instance.
91	   */
92	  public static InstanceConfig toHelixInstanceConfig(Instance instance) {
93	    InstanceConfig instanceConfig = new InstanceConfig(getHelixInstanceId(instance));
94	    instanceConfig.setInstanceEnabled(true);
95	    updateHelixInstanceConfig(instanceConfig, instance);
96	    return instanceConfig;
97	  }
98	
99	  /**
100	   * Updates the Helix InstanceConfig with the given instance configuration. Leaves the fields not included in the
101	   * instance configuration unchanged.
102	   */
103	  public static void updateHelixInstanceConfig(InstanceConfig instanceConfig, Instance instance) {
104	    ZNRecord znRecord = instanceConfig.getRecord();
105	
106	    Map<String, String> simpleFields = znRecord.getSimpleFields();
107	    simpleFields.put(InstanceConfig.InstanceConfigProperty.HELIX_HOST.name(), instance.getHost());
108	    simpleFields.put(InstanceConfig.InstanceConfigProperty.HELIX_PORT.name(), Integer.toString(instance.getPort()));
109	    int grpcPort = instance.getGrpcPort();
110	    if (grpcPort > 0) {
111	      simpleFields.put(Helix.Instance.GRPC_PORT_KEY, Integer.toString(grpcPort));
112	    } else {
113	      simpleFields.remove(Helix.Instance.GRPC_PORT_KEY);
114	    }
115	    int adminPort = instance.getAdminPort();
116	    if (adminPort > 0) {
117	      simpleFields.put(Helix.Instance.ADMIN_PORT_KEY, Integer.toString(adminPort));
118	    } else {
119	      simpleFields.remove(Helix.Instance.ADMIN_PORT_KEY);
120	    }
121	    int queryServicePort = instance.getQueryServicePort();
122	    if (queryServicePort > 0) {
123	      simpleFields.put(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_SERVICE_PORT_KEY, Integer.toString(queryServicePort));
124	    } else {
125	      simpleFields.remove(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_SERVICE_PORT_KEY);
126	    }
127	    int queryMailboxPort = instance.getQueryMailboxPort();
128	    if (queryMailboxPort > 0) {
129	      simpleFields.put(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_MAILBOX_PORT_KEY, Integer.toString(queryMailboxPort));
130	    } else {
131	      simpleFields.remove(Helix.Instance.MULTI_STAGE_QUERY_ENGINE_MAILBOX_PORT_KEY);
132	    }
133	    boolean queriesDisabled = instance.isQueriesDisabled();
134	    if (queriesDisabled) {
135	      simpleFields.put(Helix.QUERIES_DISABLED, Boolean.toString(true));
136	    } else {
137	      simpleFields.remove(Helix.QUERIES_DISABLED);
138	    }
139	
140	    Map<String, List<String>> listFields = znRecord.getListFields();
141	    List<String> tags = instance.getTags();
142	    String tagsKey = InstanceConfig.InstanceConfigProperty.TAG_LIST.name();
143	    if (CollectionUtils.isNotEmpty(tags)) {
144	      listFields.put(tagsKey, tags);
145	    } else {
146	      listFields.remove(tagsKey);
147	    }
148	
149	    Map<String, Map<String, String>> mapFields = znRecord.getMapFields();
150	    Map<String, Integer> pools = instance.getPools();
151	    if (MapUtils.isNotEmpty(pools)) {
152	      Map<String, String> mapValue = new TreeMap<>();
153	      for (Map.Entry<String, Integer> entry : pools.entrySet()) {
154	        mapValue.put(entry.getKey(), entry.getValue().toString());
155	      }
156	      mapFields.put(POOL_KEY, mapValue);
157	    } else {
158	      mapFields.remove(POOL_KEY);
159	    }
160	  }
