19	package org.apache.pinot.spi.config.instance;
20	
21	import com.fasterxml.jackson.annotation.JsonCreator;
22	import com.fasterxml.jackson.annotation.JsonProperty;
23	import com.google.common.base.Preconditions;
24	import java.util.List;
25	import java.util.Map;
26	import javax.annotation.Nullable;
27	import org.apache.pinot.spi.config.BaseJsonConfig;
28	
29	
30	/**
31	 * Instance configuration.
32	 * <pre>
33	 * Example:
34	 * {
35	 *   "host": "hostname.example.com",
36	 *   "port": 1234,
37	 *   "type": "SERVER",
38	 *   "tags": ["example_OFFLINE"],
39	 *   "pools": {
40	 *     "example_OFFLINE": 0
41	 *   },
42	 *   "grpcPort": 8090
43	 * }
44	 * </pre>
45	 */
46	public class Instance extends BaseJsonConfig {
47	  public static final int NOT_SET_GRPC_PORT_VALUE = -1;
48	  public static final int NOT_SET_ADMIN_PORT_VALUE = -1;
49	  public static final int NOT_SET_QUERY_SERVER_PORT_VALUE = -1;
50	  public static final int NOT_SET_QUERY_MAILBOX_PORT_VALUE = -1;
51	
52	  private final String _host;
53	  private final int _port;
54	  private final InstanceType _type;
55	  private final List<String> _tags;
56	  private final Map<String, Integer> _pools;
57	  private final int _grpcPort;
58	  private final int _adminPort;
59	  private final int _queryServicePort;
60	  private final int _queryMailboxPort;
61	  private final boolean _queriesDisabled;
62	
63	  @JsonCreator
64	  public Instance(@JsonProperty(value = "host", required = true) String host,
65	      @JsonProperty(value = "port", required = true) int port,
66	      @JsonProperty(value = "type", required = true) InstanceType type,
67	      @JsonProperty("tags") @Nullable List<String> tags, @JsonProperty("pools") @Nullable Map<String, Integer> pools,
68	      @JsonProperty("grpcPort") int grpcPort, @JsonProperty("adminPort") int adminPort,
69	      @JsonProperty("queryServicePort") int queryServicePort, @JsonProperty("queryMailboxPort") int queryMailboxPort,
70	      @JsonProperty("queriesDisabled") boolean queriesDisabled) {
71	    Preconditions.checkArgument(host != null, "'host' must be configured");
72	    Preconditions.checkArgument(type != null, "'type' must be configured");
73	    _host = host;
74	    _port = port;
75	    _type = type;
76	    _tags = tags;
77	    _pools = pools;
78	    if (grpcPort == 0) {
79	      _grpcPort = NOT_SET_GRPC_PORT_VALUE;
80	    } else {
81	      _grpcPort = grpcPort;
82	    }
83	    if (adminPort == 0) {
84	      _adminPort = NOT_SET_ADMIN_PORT_VALUE;
85	    } else {
86	      _adminPort = adminPort;
87	    }
88	    if (queryServicePort == 0) {
89	      _queryServicePort = NOT_SET_QUERY_SERVER_PORT_VALUE;
90	    } else {
91	      _queryServicePort = queryServicePort;
92	    }
93	    if (queryMailboxPort == 0) {
94	      _queryMailboxPort = NOT_SET_QUERY_MAILBOX_PORT_VALUE;
95	    } else {
96	      _queryMailboxPort = queryMailboxPort;
97	    }
98	    _queriesDisabled = queriesDisabled;
99	  }
100	
101	  public String getHost() {
102	    return _host;
103	  }
104	
105	  public int getPort() {
106	    return _port;
107	  }
108	
109	  public InstanceType getType() {
110	    return _type;
111	  }
112	
113	  @Nullable
114	  public List<String> getTags() {
115	    return _tags;
116	  }
117	
118	  @Nullable
119	  public Map<String, Integer> getPools() {
120	    return _pools;
121	  }
122	
123	  public int getGrpcPort() {
124	    return _grpcPort;
125	  }
126	
127	  public int getAdminPort() {
128	    return _adminPort;
129	  }
130	
131	  public int getQueryServicePort() {
132	    return _queryServicePort;
133	  }
134	
135	  public int getQueryMailboxPort() {
136	    return _queryMailboxPort;
137	  }
138	
139	  public boolean isQueriesDisabled() {
140	    return _queriesDisabled;
141	  }
142	}
