package org.apache.pinot.spi.exception;

/**
 * Exception thrown by a validator when an instance or table configuration fails validation.
 *
 * <p>This is an unchecked exception so that it can propagate through APIs that commit configuration to the cluster
 * without forcing every intermediate caller to declare or handle it. The failure message is always available via
 * {@link #getMessage()}.
 */
public class ConfigValidationException extends RuntimeException {

  public ConfigValidationException(String message) {
    super(message);
  }

  public ConfigValidationException(String message, Throwable cause) {
    super(message, cause);
  }
}
