package org.apache.pinot.spi.config.instance;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import org.apache.pinot.spi.exception.ConfigValidationException;


/**
 * Static registry for pluggable {@link InstanceConfigValidator}s.
 *
 * <p>External code can register custom validators that are automatically invoked before an instance configuration is
 * committed to the cluster. Validators are invoked in registration order, and validation short-circuits on the first
 * validator that throws a {@link ConfigValidationException}.
 *
 * <p>This class is thread-safe.
 */
public class InstanceConfigValidatorRegistry {
  private InstanceConfigValidatorRegistry() {
  }

  private static final List<InstanceConfigValidator> VALIDATORS = new CopyOnWriteArrayList<>();

  /**
   * Registers a validator. Validators are invoked in the order they are registered.
   */
  public static void register(InstanceConfigValidator validator) {
    VALIDATORS.add(validator);
  }

  /**
   * Invokes all registered validators, in registration order, on the given instance. This is a no-op when no
   * validators are registered. If a validator throws a {@link ConfigValidationException}, the exception is propagated
   * and the remaining validators are not invoked.
   */
  public static void validate(Instance instance)
      throws ConfigValidationException {
    for (InstanceConfigValidator validator : VALIDATORS) {
      validator.validate(instance);
    }
  }

  /**
   * Clears all registered validators.
   */
  public static void reset() {
    VALIDATORS.clear();
  }
}
